import type { HTTPError } from "../../error.ts";

// prettier-ignore
const statusTitles: Record<number, string> = {
  400: "Bad Request", 401: "Unauthorized", 402: "Payment Required", 403: "Forbidden",
  404: "Not Found", 405: "Method Not Allowed", 406: "Not Acceptable", 408: "Request Timeout",
  409: "Conflict", 410: "Gone", 411: "Length Required", 412: "Precondition Failed",
  413: "Content Too Large", 414: "URI Too Long", 415: "Unsupported Media Type",
  416: "Range Not Satisfiable", 417: "Expectation Failed", 418: "I'm a Teapot",
  421: "Misdirected Request", 422: "Unprocessable Entity", 423: "Locked", 424: "Failed Dependency",
  425: "Too Early", 426: "Upgrade Required", 428: "Precondition Required",
  429: "Too Many Requests", 431: "Request Header Fields Too Large",
  451: "Unavailable For Legal Reasons", 500: "Internal Server Error", 501: "Not Implemented",
  502: "Bad Gateway", 503: "Service Unavailable", 504: "Gateway Timeout",
  505: "HTTP Version Not Supported", 507: "Insufficient Storage", 508: "Loop Detected",
  511: "Network Authentication Required",
};

const reservedKeys = new Set(["type", "title", "status", "detail", "instance"]);

/**
 * Build an RFC 9457 problem details body from an `HTTPError`.
 */
export function toProblemBody(error: HTTPError, debug?: boolean): Record<string, unknown> {
  const { status, unhandled } = error;
  const title = (!unhandled && error.statusText) || statusTitles[status];
  const detail =
    !unhandled && error.message !== title && error.message !== `HTTPError ${status}`
      ? error.message
      : undefined;

  const problem: Record<string, unknown> = {
    type: unhandled ? undefined : error.type,
    title,
    status,
    detail,
    instance: unhandled ? undefined : error.instance,
  };

  if (!unhandled) {
    if (error.body) {
      for (const key of Object.keys(error.body)) {
        if (!reservedKeys.has(key)) {
          problem[key] = error.body[key];
        }
      }
    }
    problem.data = error.data;
  }

